python -c "
import json, sys, os, time
from pathlib import Path

transcript = sys.stdin.read()
if not transcript.strip():
    sys.exit(0)

try:
    events = [json.loads(line) for line in transcript.splitlines() if line.strip()]
except json.JSONDecodeError:
    sys.exit(0)

if not events:
    sys.exit(0)

task = ''
for e in events:
    if e.get('type') == 'user' and e.get('message', {}).get('role') == 'user':
        content = e['message'].get('content', '')
        if isinstance(content, str):
            task = content[:500]
            break

# collect tool_calls and failures
tool_calls = []
failures = []
final_output = ''
ok = True

for e in events:
    if e.get('type') == 'assistant':
        msg = e.get('message', {})
        content = msg.get('content', [])
        if isinstance(content, list):
            for c in content:
                if c.get('type') == 'tool_use':
                    tool_calls.append({
                        'name': c.get('name', ''),
                        'args': json.dumps(c.get('input', {})),
                        'result': ''
                    })
    elif e.get('type') == 'tool_result':
        tool_use_id = e.get('tool_use_id', '')
        result = e.get('content', '')
        if isinstance(result, list):
            for r in result:
                if r.get('type') == 'text':
                    result = r.get('text', '')
                    break
        for tc in reversed(tool_calls):
            if tc.get('id') == tool_use_id:
                tc['result'] = result[:2000]
                break
    elif e.get('type') == 'error':
        ok = False
        failures.append({'reason': 'session error', 'detail': e.get('message', '')[:1000]})

for e in reversed(events):
    if e.get('type') == 'assistant':
        msg = e.get('message', {})
        content = msg.get('content', '')
        if isinstance(content, str):
            final_output = content[:3000]
            break

from datetime import datetime
trace = {
    'task': task,
    'events': [],
    'output': final_output,
    'ok': ok,
    'created_at': datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
}

for tc in tool_calls:
    trace['events'].append({
        'kind': 'tool_call',
        'name': tc['name'],
        'args': tc['args'],
        'result': tc['result']
    })

for f in failures:
    trace['events'].append({
        'kind': 'failure',
        'reason': f['reason'],
        'detail': f['detail']
    })

traces_dir = Path(__file__).parent.parent / 'traces'
traces_dir.mkdir(parents=True, exist_ok=True)
tid = datetime.utcnow().strftime('%Y%m%dT%H%M%S')
path = traces_dir / f'{tid}.jsonl'
path.write_text(json.dumps(trace) + '
', encoding='utf-8')
print(f'[sevolve] captured trace: {path}', file=sys.stderr)
"
